clc; clear; close all;

%Taking the No of Iteration as Input - Iteration/100 = Time of Simulation
N = input("Enter the Number of Iteration (Generally 6000 - 10000): ");
K = input("Enter the Navigation Constant (Generally 3-5): ");

% Initializing the Target Position
xt = NaN(1,N+1);
yt = NaN(1,N+1);

% Initializing the Missile's Position
xm = NaN(1,N+1);
ym = NaN(1,N+1);

% Target Trajectory
xt(1) = 10000; yt(1) = 15000; %m --- Initial Position
Vtx = -490; Vty = 5;  %m/s
atx = 2.5; aty = 10; %m/s^2

thetat = NaN(1,N+1);
Dist = NaN(1,N+1);%Distance Between the Missile and Target
Time = NaN(1,N+1);

%%Assuming after the boost phase of the missile it has reached this position and Velocity 
Vxm = 540;%m/s - Missile
Vym = 350;%m/s - Missile
xm(1) = 0; ym(1) = 0;
dt = 0.01;
Time(1) = dt;
Dist(1) = sqrt((xm(1) - xt(1))^2 + (ym(1) - yt(1))^2);
thetat(1) = atan2(yt(1) - ym(1),xt(1) - xm(1));
fprintf("Initial Distance between the Target and Missile is: %.2f\n",Dist(1)); %[output:826a2b9e]


for i = 1:N
    %Updating Target position
    xt(i+1) = xt(i) + Vtx*dt + 0.5*atx*dt^2;
    yt(i+1) = yt(i) + Vty*dt + 0.5*aty*dt^2;

    %Updating Target Velocity
    Vtx = Vtx + atx*dt;
    Vty = Vty + aty*dt;

    thetat(i+1) = atan2(yt(i+1) - ym(i),xt(i+1) - xm(i));  % Update the angle based on the new target position
    thetat_dot = (thetat(i+1) - thetat(i))/dt;

    Dist(i+1) = sqrt((xt(i+1) - xm(i))^2 + (yt(i+1) - ym(i))^2);
    R_dot = (Dist(i+1) - Dist(i))/dt;
    Vc = -R_dot; % positive when closing
    am = K*Vc*thetat_dot;%Latex Command

    %Direction of Latex Command is the LOS rate direction and Perpendicular to velocity 
    amx = -am*Vym/sqrt(Vxm^2 + Vym^2);
    amy = am*Vxm/sqrt(Vxm^2 + Vym^2);

    % Calculate missile's velocity components
    Vxm = Vxm + amx*dt;
    Vym = Vym + amy*dt;

    %Updating missile's position
    xm(i+1) = xm(i) + Vxm*dt + 0.5*amx*dt^2;
    ym(i+1) = ym(i) + Vym*dt + 0.5*amy*dt^2;

    Time(i+1) = (i+1)*dt;
    %For Debugging 
    %fprintf("i=%d | R=%.2f | Rdot=%.2f | thetadot=%.4f | am=%.2f\n", i, Dist(i), R_dot, thetat_dot, am);

    if (Dist(i+1) < 5)
        break;
    end
    
  
end
if (min(Dist) > 500)
    fprintf("The Target accelerated and got out of reach!\n");
end

if (min(Dist) <= 50) %[output:group:18f67b58]
    fprintf("Mission Succesfull! Target Eliminated\n"); %[output:8fbb6d42]

end %[output:group:18f67b58]

%Plotting the Target Trajectory
figure; %[output:6efaf834]
plot(xt,yt,marker = "o", Color = "r"); %[output:6efaf834]
title("Target's Trajectory") %[output:6efaf834]
xlabel("X Coordinate"); %[output:6efaf834]
ylabel("Y Coordinate"); %[output:6efaf834]
hold on; %[output:6efaf834]
plot(xm,ym,marker = "*", Color = "g"); %[output:6efaf834]
title("Missile's Trajectory") %[output:6efaf834]
xlabel("X Coordinate"); %[output:6efaf834]
ylabel("Y Coordinate"); %[output:6efaf834]
grid on; %[output:6efaf834]

figure; %[output:58619050]
plot(Time,Dist,marker = "+", Color = "b"); %[output:58619050]
title("Reletive distance between the Missile and Interceptor!") %[output:58619050]
xlabel("Time in seconds"); %[output:58619050]
ylabel("Distance b/w the Target and Missile"); %[output:58619050]

fprintf("Time taken to reach closest distance of %.2f m to the Target is: %.2f seconds\n",min(Dist),Time(i+1)); %[output:3d671d2b]

fprintf("Final Distance between the Target and Missile is: %.2f\n",sqrt((xm(i+1) - xt(i+1))^2 + (ym(i+1) - yt(i+1))^2)); %[output:0ac54ba2]

fprintf("Minimum Distance between the Target and Missile is: %.2f\n",min(Dist)); %[output:7319f7db]


